use crate::{ivp_managed_response::{ResponseWorld,Body,Object,Feature,Settings},ivp_contact_pipeline::CoreFrame,ivp_contact::Core,ivp_create::{Endpoint,Feature as CompactFeature},ivp_managed_contacts::Settings as AdmissionSettings,ivp_refresh,ivp_unit_registry::Registry};
use bevy::prelude::*;
use serde_json::Value;
fn f(v:&Value)->f32{v.as_f64().unwrap() as f32}
fn vec(v:&Value)->Vec3{Vec3::from_array(std::array::from_fn(|i|f(&v[i])))}
fn rows(v:&Value)->[Vec3;3]{std::array::from_fn(|i|vec(&v[i]))}
fn endpoint(e:&Value)->Endpoint{let v=&e["feature"];Endpoint{object:e["object"].as_u64().unwrap(),feature:CompactFeature{kind:v["kind"].as_i64().unwrap() as i16,edge:v["edge"].as_u64().unwrap(),opposite:v["opposite"].as_u64().unwrap(),triangle:v["triangle"].as_u64().unwrap(),ledge:v["ledge"].as_u64().unwrap(),vertex:v["vertex"].as_u64().unwrap() as u16,vertices:rows(&v["vertices"])}}}
fn world(c:&Value)->ResponseWorld{
    let mut registry=Registry::new(4);let bodies=c["bodies"].as_array().unwrap().iter().enumerate().map(|(i,v)|{let flags=v["flags"].as_u64().unwrap() as u16;registry.register_core(i,flags&2!=0).unwrap();Body{flags,core:Core{inverse_mass:f(&v["inverse_mass"]),inverse_inertia:vec(&v["inverse_inertia"]),linear:vec(&v["linear"]),angular:vec(&v["angular"]),pending_linear:vec(&v["pending_linear"]),pending_angular:vec(&v["pending_angular"])},frame:CoreFrame{rotation:Mat3::from_cols_array_2d(&rows(&v["rotation"]).map(|v|v.to_array())).transpose(),position:vec(&v["position"])},stamps:std::array::from_fn(|i|v["stamps"][i].as_f64().unwrap())}}).collect();
    let objects=(0..2).map(|side|{let e=&c["endpoints"][side];let core=e["object"].as_u64().unwrap() as usize-1;let s=&c["shapes"][side];let m=&c["bodies"][core]["material"];(core as u64+1,Object{core,rotation:rows(&s["rotation"]),translation:vec(&s["translation"]),radius:f(&s["radius"]),material_flags:m["flags"].as_u64().unwrap() as u32,friction:f(&m["friction"])})}).collect();
    let k=&c["settings"];ResponseWorld::new(registry,bodies,objects,Settings{dt:f(&c["dt"]),admission:AdmissionSettings{distance:f(&k["distance"]),area_epsilon:k["area_epsilon"].as_f64().unwrap()},refresh:ivp_refresh::Settings{epsilon:f(&k["epsilon"]),bary_bias:f(&k["bary_bias"]),area_epsilon:k["area_epsilon"].as_f64().unwrap(),one:f(&k["one"]),opposite:f(&k["opposite"])},threshold_extra:f(&k["threshold_extra"]),minimum_impulse:f(&k["minimum_impulse"]),minimum_determinant_squared:f(&k["minimum_determinant_squared"])},c["time"].as_f64().unwrap()).unwrap()
}
fn features(c:&Value)->[Feature;2]{std::array::from_fn(|i|Feature{material_code:0,endpoint:endpoint(&c["endpoints"][i]),vertices:rows(&c["shapes"][i]["vertices"]),canonical:rows(&c["shapes"][i]["canonical"])})}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){
    (Value::Object(a),Value::Object(b))=>for(k,v)in a{compare(v,&b[k],&format!("{path}.{k}"));},
    (Value::Array(a),Value::Array(b))=>{assert_eq!(a.len(),b.len(),"{path}");for(i,(a,b))in a.iter().zip(b).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},
    (Value::Number(a),Value::Number(b))=>{if path.ends_with(".time")||path.contains(".stamps["){assert_eq!(a.as_f64().unwrap().to_bits(),b.as_f64().unwrap().to_bits(),"{path}");}else if a.is_f64()||b.is_f64(){assert_eq!((a.as_f64().unwrap() as f32).to_bits(),(b.as_f64().unwrap() as f32).to_bits(),"{path}: {a} vs {b}");}else{assert_eq!(a,b,"{path}");}},
    _=>assert_eq!(a,b,"{path}"),
}}

fn configured(c:&Value)->ResponseWorld{let mut b=c.clone();b["endpoints"]=c["births"][0]["endpoints"].clone();b["shapes"]=c["births"][0]["shapes"].clone();world(&b).with_energy(c["bodies"].as_array().unwrap().iter().map(|v|crate::ivp_batch_normal::Physical{flags:v["flags"].as_u64().unwrap() as u16,mass:f(&v["mass"]),inertia:vec(&v["inertia"])}).collect(),f(&c["allowance_factor"]),f(&c["energy_bound"])).unwrap()}
fn replay_batch(c:&Value,check:bool)->(Vec<Value>,[usize;3]){
 let mut w=configured(c);let mut all=vec![];
 for b in c["births"].as_array().unwrap(){let mut input=c.clone();input["endpoints"]=b["endpoints"].clone();input["shapes"]=b["shapes"].clone();let id=w.resolve(0xc0000,features(&input),Some(1)).unwrap().unwrap();let actual=w.snapshot(id);if check{compare(&actual,&b["numeric"],&format!("world{} birth{id}",c["scenario"]));}all.push(actual);}
 let initial=w.batch_snapshot(0);if check{compare(&initial,&c["states"][0]["output"],"initial batch");}all.push(initial);
 for (i,row) in c["states"].as_array().unwrap().iter().enumerate().skip(1){w.advance(1,vec(&row["kick"]),vec(&row["angular"]),vec(&row["shift"])).unwrap();let retired=w.normal_prepared_control(0,row["refresh"].as_bool().unwrap()).unwrap();assert_eq!(retired,i==13);let actual=w.batch_snapshot(0);if check{compare(&actual,&row["output"],&format!("world{} normal{i}",c["scenario"]));}all.push(actual);}
 let counts=w.batch_report_counts();
 let(effects,ids,releases)=w.take_effects();assert_eq!(ids.len(),c["births"].as_array().unwrap().len());assert_eq!(releases.len(),ids.len());assert_eq!(effects.iter().filter(|e|matches!(e,crate::ivp_unit_registry::Effect::ResetClock(_))).count(),2*ids.len());assert!(w.diagnostics()["metadata"]["contact_bindings"].as_array().unwrap().is_empty());(all,counts)
}
pub(crate) fn verify(){let data:Value=serde_json::from_str(include_str!("../tools/fixtures/native-ivp-contact-batch-normal.json")).unwrap();let mut total=0;let mut counts=[0;3];for c in data["cases"].as_array().unwrap(){let(actual,n)=replay_batch(c,true);total+=actual.len();for i in 0..3{counts[i]+=n[i];}let mut corrupt=c.clone();for b in corrupt["births"].as_array_mut().unwrap(){b["numeric"]=Value::Null;}for row in corrupt["states"].as_array_mut().unwrap(){row["output"]=Value::Null;}assert_eq!(actual,replay_batch(&corrupt,false).0);}assert_eq!(total,128);assert_eq!(counts,[88,8,0]);println!("coupled native normals: {} checkpoints; fast/fallback/reject counts {:?}; retained state, order, clocks and retirement match",total,counts);}

pub(crate) fn invalid(){let data:Value=serde_json::from_str(include_str!("../tools/fixtures/native-ivp-contact-batch-normal.json")).unwrap();let c=&data["cases"][0];let mut w=configured(c);for b in c["births"].as_array().unwrap(){let mut input=c.clone();input["endpoints"]=b["endpoints"].clone();input["shapes"]=b["shapes"].clone();w.resolve(0xc0000,features(&input),Some(1)).unwrap();}let before=(w.batch_snapshot(0),w.diagnostics());assert!(w.normal(0).is_err());assert!(w.normal_prepared_control(999,false).is_err());assert_eq!(before,(w.batch_snapshot(0),w.diagnostics()));
 let mut b=c.clone();b["endpoints"]=c["births"][0]["endpoints"].clone();b["shapes"]=c["births"][0]["shapes"].clone();let mut missing=world(&b);for birth in c["births"].as_array().unwrap(){b["endpoints"]=birth["endpoints"].clone();b["shapes"]=birth["shapes"].clone();missing.resolve(0xc0000,features(&b),Some(1)).unwrap();}let before=(missing.batch_snapshot(0),missing.diagnostics());assert!(missing.normal_prepared_control(0,false).is_err());assert_eq!(before,(missing.batch_snapshot(0),missing.diagnostics()));}
#[test]fn native_coupled_normal_continuation_matches(){verify();}
#[test]fn coupled_normal_missing_context_and_phase_errors_are_atomic(){invalid();}
